 if(fabs(dz)<1e-14){if(z<4.9||z>5.1)return;}else{double t1=(4.9-z)/dz,t2=(5.1-z)/dz;if(t1>t2)swap(t1,t2);a=max(a,t1);b=min(b,t2);}
